package com.example.taxis.controller.web;
import com.example.taxis.dto.request.*;import com.example.taxis.exception.BusinessException;import com.example.taxis.service.ApplicationService;import java.math.BigDecimal;import java.time.LocalDateTime;import org.springframework.data.domain.PageRequest;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class PortalController{
 private final ApplicationService service;public PortalController(ApplicationService service){this.service=service;}
 @GetMapping("/client") String client(Authentication a,Model m){var c=service.getClientByEmail(a.getName());m.addAttribute("client",c);m.addAttribute("rides",service.listRide("","","clientId:"+c.id(),PageRequest.of(0,100)).content());m.addAttribute("drivers",service.listDriver("","","",PageRequest.of(0,100)).content());m.addAttribute("title","Espace client");return "client-dashboard";}
 @PostMapping("/client/rides") String order(Authentication a,@RequestParam String departure,@RequestParam String destination,@RequestParam BigDecimal distance,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime scheduledAt,@RequestParam Integer passengers,RedirectAttributes f){try{var c=service.getClientByEmail(a.getName());service.createRide(new RideRequest(c.id(),departure,destination,distance,scheduledAt,passengers));f.addFlashAttribute("success","Demande de taxi créée");}catch(BusinessException e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/client";}
 @PostMapping("/client/rides/{id}/cancel") String cancel(Authentication a,@PathVariable Long id,RedirectAttributes f){var c=service.getClientByEmail(a.getName());var r=service.getRide(id);if(!c.id().equals(r.clientId())||!"EN_ATTENTE".equals(r.status())){f.addFlashAttribute("error","Annulation impossible");return "redirect:/client";}service.perform("Ride",id,"cancel",ActionRequest.empty());f.addFlashAttribute("success","Demande annulée");return "redirect:/client";}
 @GetMapping("/chauffeur") String driver(Authentication a,Model m){var d=service.getDriverByEmail(a.getName());m.addAttribute("driver",d);m.addAttribute("vehicle",service.getVehicleByDriver(d.id()));m.addAttribute("available",service.listRide("","EN_ATTENTE","",PageRequest.of(0,100)).content());m.addAttribute("mine",service.listRide("","","driverId:"+d.id(),PageRequest.of(0,100)).content());m.addAttribute("clients",service.listClient("","","",PageRequest.of(0,100)).content());m.addAttribute("title","Espace chauffeur");return "driver-dashboard";}
 @PostMapping("/chauffeur/rides/{id}/accept") String accept(Authentication a,@PathVariable Long id,RedirectAttributes f){try{var d=service.getDriverByEmail(a.getName());service.acceptRide(id,d.id());f.addFlashAttribute("success","Course acceptée");}catch(BusinessException e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/chauffeur";}
 @PostMapping("/chauffeur/rides/{id}/{action}") String action(Authentication a,@PathVariable Long id,@PathVariable String action,RedirectAttributes f){var d=service.getDriverByEmail(a.getName());var r=service.getRide(id);if(!d.id().equals(r.driverId())){f.addFlashAttribute("error","Course inaccessible");return "redirect:/chauffeur";}try{service.perform("Ride",id,action,ActionRequest.empty());f.addFlashAttribute("success","Course mise à jour");}catch(BusinessException e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/chauffeur";}
}
